From f8c1c87d76630fe79da753cf9b0e1aff673af075 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:12:19 +0100
Subject: [PATCH] applet: add a button to add a new connection

Adding a connection, like a hidden Wi-Fi network or a VPN, meant opening
the settings page and finding its add button. The widget's toolbar now has
an Add Connection button that opens the connection type chooser directly.

BUG: 449443
---
 applet/Toolbar.qml                | 20 +++++++++++++++++++-
 kcms/kcm_connections/kcm.cpp      |  9 +++++++++
 kcms/kcm_connections/qml/main.qml |  7 ++++++-
 3 files changed, 34 insertions(+), 2 deletions(-)

diff --git a/applet/Toolbar.qml b/applet/Toolbar.qml
index dfa0642f7..54d6e72ef 100644
--- a/applet/Toolbar.qml
+++ b/applet/Toolbar.qml
@@ -215,7 +215,7 @@ RowLayout {
         focus: mainWindow.expanded && !Kirigami.InputMethod.willShowOnActive

         KeyNavigation.left: hotspotButton.visible ? hotspotButton : hotspotButton.KeyNavigation.left
-        KeyNavigation.right: openEditorButton
+        KeyNavigation.right: addConnectionButton.visible ? addConnectionButton : openEditorButton

         onTextChanged: {
             appletProxyModel.setFilterFixedString(text)
@@ -242,6 +242,24 @@ RowLayout {
         onClicked: qrca.launch()
     }

+    PlasmaComponents3.ToolButton {
+        id: addConnectionButton
+
+        visible: mainWindow.kcmAuthorized
+
+        icon.name: "list-add"
+        text: i18nc("@action:button", "Add Connection…")
+        display: PlasmaComponents3.ToolButton.IconOnly
+
+        PlasmaComponents3.ToolTip {
+            text: addConnectionButton.text
+        }
+
+        onClicked: {
+            KCMUtils.KCMLauncher.openSystemSettings(mainWindow.kcm, ["--args", "AddConnection"])
+        }
+    }
+
     PlasmaComponents3.ToolButton {
         id: openEditorButton

diff --git a/kcms/kcm_connections/kcm.cpp b/kcms/kcm_connections/kcm.cpp
index 3a02834f4..9d30cc33a 100644
--- a/kcms/kcm_connections/kcm.cpp
+++ b/kcms/kcm_connections/kcm.cpp
@@ -176,6 +176,11 @@ KCMNetworkmanagement::KCMNetworkmanagement(QObject *parent, const KPluginMetaDat
             return;
         }

+        if (args.contains(QStringLiteral("AddConnection"))) {
+            QMetaObject::invokeMethod(m_ui->connectionView->rootObject(), "showAddConnectionDialog");
+            return;
+        }
+
         if (const auto connection = connectionFromArgs(args); isSelectable(connection)) {
             selectConnection(connection);
         }
@@ -187,6 +192,10 @@ KCMNetworkmanagement::KCMNetworkmanagement(QObject *parent, const KPluginMetaDat
         QTimer::singleShot(0, this, [this, vpnFile] {
             promptImportVpn(vpnFile);
         });
+    } else if (args.contains(QStringLiteral("AddConnection"))) {
+        QTimer::singleShot(0, this, [this] {
+            QMetaObject::invokeMethod(m_ui->connectionView->rootObject(), "showAddConnectionDialog");
+        });
     }

     // Select the connection from the arguments, falling back to a default one
diff --git a/kcms/kcm_connections/qml/main.qml b/kcms/kcm_connections/qml/main.qml
index 57a283a79..930b1e2fd 100755
--- a/kcms/kcm_connections/qml/main.qml
+++ b/kcms/kcm_connections/qml/main.qml
@@ -152,7 +152,7 @@ QQC2.Page {
             QQC2.ToolTip.visible: hovered

             onClicked: {
-                addNewConnectionDialog.show()
+                root.showAddConnectionDialog()
             }
         }

@@ -303,6 +303,11 @@ QQC2.Page {
         handler: handler
     }

+    function showAddConnectionDialog() {
+        addNewConnectionDialog.show();
+        addNewConnectionDialog.requestActivate();
+    }
+
     function showConfigurationDialog() {
         configurationDialog.show();
         configurationDialog.requestActivate();
-- 
